 * @returns the durable run payload.
 */
export function runRecord(attempt: number, status: 'pass' | 'fail', isolation: CertificateIsolation = 'none'): Raw {
  return {
    kind: 'verification/run',
    version: 1,
    standard: { id: 'standard-1', revision: 1 },
